32		}
33		svc.nowAt(func() time.Time {
34			f.clock = f.clock.Add(time.Minute)
35			return f.clock
36		})
37		return f
38	}
39	
40	// reopen 模拟退出后重新打开，数据与处理进度必须仍在。
41	func (f *fixture) reopen(t *testing.T) {
42		t.Helper()
43		store, err := Open(f.store.Path())
44		if err != nil {
45			t.Fatalf("reopen: %v", err)
46		}
