475			t.Fatalf("已确认项不能重新提交，got %v", err)
476		}
477		// 补充并重新提交：只有该项恢复待处理，既有接收结果不变。
478		if _, err := f.svc.ResubmitReturned(h.ID, idA, " 张三 ", "图纸编号已补到资料柜B层"); err != nil {
479			t.Fatalf("resubmit: %v", err)
480		}
481		got, _ = f.svc.GetHandover(h.ID)
482		var ea, eb *HandoverEntry
483		for i := range got.Entries {
484			switch got.Entries[i].ItemID {
485			case idA:
486				ea = &got.Entries[i]
487			case idB:
488				eb = &got.Entries[i]
489			}
490		}
491		if ea.Status != EntryPending {
492			t.Fatalf("重新提交后该项应恢复待处理，got %s", ea.Status)
493		}
494		if eb.Status != EntryConfirmed {
495			t.Fatalf("既有接收结果不应改变，got %s", eb.Status)
496		}
497		if got.Completed() {
498			t.Fatalf("恢复待处理后交接应再次未完成")
499		}
500		r := ea.Rounds[len(ea.Rounds)-1]
501		if r.Reason != "信息不全，需补充图纸" || r.Supplement != "图纸编号已补到资料柜B层" {
502			t.Fatalf("原文退回原因与补充说明都应保留：%+v", r)
503		}
504		if r.SupplementOperator != "张三" || r.ResubmittedAt == nil {
505			t.Fatalf("应记录补充操作人与重新提交时间：%+v", r)
506		}
507	
508		// 重新提交后再次退回，产生第 2 轮历史；再确认接收。
509		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "仍缺签字", "", ""); err != nil {
510			t.Fatalf("second return: %v", err)
511		}
512		got, _ = f.svc.GetHandover(h.ID)
513		for i := range got.Entries {
514			if got.Entries[i].ItemID == idA {
515				ea = &got.Entries[i]
516			}
517		}
518		if len(ea.Rounds) != 2 {
519			t.Fatalf("应保留历次退回记录，期望2轮，got %d", len(ea.Rounds))
520		}
521		if ea.Rounds[0].Reason != "信息不全，需补充图纸" {
522			t.Fatalf("第一轮退回原因不得覆盖：%+v", ea.Rounds[0])
523		}
524		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "签字已补齐"); err != nil {
525			t.Fatalf("resubmit2: %v", err)
526		}
527		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
528			t.Fatalf("final confirm: %v", err)
529		}
530		got, _ = f.svc.GetHandover(h.ID)
531		if !got.Completed() {
532			t.Fatalf("最终应完成")
533		}
534	}
